const DATA=[{"id": 1, "judul": "Infeksi Saluran Kemih (ISK): Sistitis, Pielonefritis, Bakteriuria Asimtomatik", "kat": "Nefrologi", "ciri": "E. coli uropatogenik penyebab tersering; demam + nyeri pinggang (CVA positif) = pielonefritis.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "ISK", "x": "Infeksi mikroba pada saluran kemih; ISK bawah = sistitis, ISK atas = pielonefritis."}, {"l": "ISK kompleks", "x": "Ada tanda sistemik (demam, nyeri pinggang), obstruksi saluran kemih atas, atau keterlibatan parenkim ginjal; faktor pemberat: kateter, DM, kehamilan, imunosupresi, pria."}, {"l": "Kuman", "x": "E. coli (UPEC) tersering; juga Klebsiella, Proteus (urease, memicu batu struvit), Enterococcus, S. saprophyticus (wanita muda)."}, {"l": "Faktor risiko", "x": "Perempuan (uretra pendek), aktivitas seksual, menopause, obstruksi, kateter, DM, refluks vesikoureter."}], "src": "(EAU, 2026b; Trautner et al., 2025)"}, {"t": "Patofisiologi", "items": [{"l": "Jalur asending", "x": "Kuman dari perineum naik ke buli lewat uretra; menempel pada uroepitel dengan fimbria (tipe 1 dan P)."}, {"l": "Jalur hematogen", "x": "Jarang (S. aureus, Candida); lebih sering pada neonatus dan imunokompromais."}, {"l": "Pertahanan penjamu", "x": "Aliran urin dan pengosongan buli tuntas, lapisan GAG/mukus, pH urin, IgA sekretorik; gangguan pertahanan memudahkan infeksi."}, {"l": "Pielonefritis", "x": "Infeksi parenkim memicu infiltrasi neutrofil dan edema interstisial; dapat meninggalkan parut ginjal."}], "src": "(Kumar et al., 2023; Loscalzo et al., 2022)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Sistitis", "x": "Disuria, frekuensi, urgensi, nyeri suprapubik, ± hematuria; tanpa demam."}, {"l": "Pielonefritis akut", "x": "Demam, menggigil, nyeri pinggang/ketok CVA positif, mual-muntah, ± gejala sistitis."}, {"l": "Bakteriuria asimtomatik", "x": "Biakan positif tanpa gejala; tidak diobati kecuali pada ibu hamil atau sebelum prosedur urologi yang berisiko perdarahan mukosa."}, {"l": "Usia ekstrem", "x": "Bayi: demam tak jelas, rewel, muntah; lansia: gejala atipikal (delirium, jatuh)."}], "src": "(EAU, 2026b)"}, {"t": "Diagnosis", "items": [{"l": "Urinalisis", "x": "Piuria, leukosit esterase dan nitrit positif, hematuria."}, {"l": "Kultur urin", "x": "Pancar tengah/kateter; ambang klasik ≥100.000 CFU/mL, EAU menerima ≥1.000 (sistitis tanpa komplikasi) dan ≥10.000 (pielonefritis tanpa komplikasi) bila bergejala."}, {"l": "Pencitraan", "x": "USG/CT bila curiga obstruksi, abses, batu, atau tidak membaik dalam 72 jam."}, {"l": "Penunjang lain", "x": "Darah lengkap, CRP, kreatinin; kultur darah pada pielonefritis berat/sepsis; tes kehamilan pada wanita usia subur."}], "src": "(EAU, 2026b)"}, {"t": "Tatalaksana", "items": [{"l": "Sistitis tanpa komplikasi", "x": "Pilihan: nitrofurantoin, fosfomisin dosis tunggal, pivmesilinam; sesuaikan pola resistensi lokal dan hindari fluorokuinolon sebagai lini pertama."}, {"l": "Pielonefritis tanpa komplikasi", "x": "Ringan: antibiotik oral (fluorokuinolon atau sefalosporin); berat: rawat inap, sefalosporin generasi 3 IV, aminoglikosida, atau karbapenem bila curiga ESBL."}, {"l": "ISK kompleks", "x": "Kendalikan sumber (drainase obstruksi, ganti kateter); durasi lebih singkat (sekitar 7 hari) dapat dipertimbangkan bila respons klinis cepat."}, {"l": "ISK berulang", "x": "Edukasi, hidrasi, estrogen vaginal pada pascamenopause, profilaksis dosis rendah bila perlu (≥3 episode/tahun atau ≥2 dalam 6 bulan)."}], "src": "(EAU, 2026b; Trautner et al., 2025; Anger et al., 2019)"}, {"t": "Komplikasi", "items": [{"l": "Urosepsis", "x": "Respons sistemik berat akibat ISK atas atau obstruksi terinfeksi."}, {"l": "Abses", "x": "Abses ginjal/perinefrik; pielonefritis emfisematosa pada DM."}, {"l": "Pionefrosis", "x": "Hidronefrosis terinfeksi, emergensi urologi."}, {"l": "Jangka panjang", "x": "Parut ginjal dan CKD (terutama anak dengan refluks); persalinan prematur pada ISK saat hamil."}], "src": "(Kumar et al., 2023; EAU, 2026b)"}]}, {"id": 2, "judul": "Glomerulonefritis Akut Pascastreptokokus (GNAPS)", "kat": "Nefrologi", "ciri": "Anak, 1–3 minggu pasca faringitis atau 3–6 minggu pasca pioderma; C3 turun; humps subepitelial.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "GNAPS", "x": "Sindrom nefritik akut setelah infeksi Streptococcus β-hemolitikus grup A strain nefritogenik."}, {"l": "Masa laten", "x": "1–3 minggu setelah faringitis; 3–6 minggu setelah pioderma/impetigo."}, {"l": "Epidemiologi", "x": "Terutama anak usia sekolah; lebih sering di negara berkembang dengan sanitasi kurang."}], "src": "(Kumar et al., 2023; KDIGO Glomerular Diseases Work Group, 2021)"}, {"t": "Patofisiologi", "items": [{"l": "Kompleks imun", "x": "Antigen streptokokus terdeposit di glomerulus lalu mengaktifkan komplemen (jalur alternatif)."}, {"l": "Inflamasi", "x": "Infiltrasi neutrofil/monosit dan proliferasi endokapiler menurunkan LFG."}, {"l": "Retensi Na dan air", "x": "Hipervolemia menyebabkan edema dan hipertensi."}, {"l": "Histologi", "x": "Mikroskop cahaya: glomerulus hiperselular; IF: granular IgG/C3 (starry sky); EM: humps subepitelial."}], "src": "(Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Trias nefritik", "x": "Hematuria (urin seperti teh/cola), edema (periorbital), hipertensi."}, {"l": "Oliguria", "x": "Penurunan produksi urin akibat LFG turun."}, {"l": "Berat", "x": "Sakit kepala/ensefalopati hipertensif, sesak karena kongesti sirkulasi."}], "src": "(Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Urinalisis", "x": "Hematuria dismorfik, silinder eritrosit, proteinuria ringan-sedang."}, {"l": "Bukti infeksi GAS", "x": "ASTO atau anti-DNase B meningkat; kultur swab tenggorok/kulit."}, {"l": "Komplemen", "x": "C3 turun dan kembali normal dalam 6–8 minggu; menetap >12 minggu menandakan GN lain (mis. C3 glomerulopati, MPGN)."}, {"l": "Fungsi ginjal", "x": "Ureum/kreatinin meningkat; biopsi hanya bila atipikal atau perjalanan tidak lazim."}], "src": "(Loscalzo et al., 2022; KDIGO Glomerular Diseases Work Group, 2021)"}, {"t": "Tatalaksana", "items": [{"l": "Suportif", "x": "Restriksi garam dan cairan, istirahat, pantau tekanan darah dan diuresis."}, {"l": "Diuretik & antihipertensi", "x": "Diuretik loop dan antihipertensi (mis. CCB); ACEi/ARB dengan hati-hati karena risiko hiperkalemia."}, {"l": "Antibiotik", "x": "Penisilin untuk eradikasi kuman dan mencegah penularan; steroid tidak rutin."}, {"l": "Dialisis", "x": "Pada gagal ginjal berat, hiperkalemia atau overload cairan refrakter."}], "src": "(Loscalzo et al., 2022; KDIGO Glomerular Diseases Work Group, 2021)"}, {"t": "Komplikasi", "items": [{"l": "Ensefalopati hipertensif", "x": "Kejang, penurunan kesadaran."}, {"l": "Gagal jantung/edema paru", "x": "Akibat overload cairan."}, {"l": "AKI", "x": "Biasanya reversibel."}, {"l": "Progresi", "x": "Sebagian kecil menjadi GN kresentik atau CKD; prognosis anak umumnya baik."}], "src": "(Kumar et al., 2023)"}]}, {"id": 3, "judul": "Sindrom Nefrotik", "kat": "Nefrologi", "ciri": "Proteinuria masif + hipoalbuminemia + edema + hiperlipidemia; anak = MCD, dewasa = membranous/FSGS.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Sindrom nefrotik", "x": "Proteinuria masif (dewasa >3,5 g/hari; anak ≥40 mg/m²/jam atau rasio protein/kreatinin ≥2 mg/mg), hipoalbuminemia, edema, hiperlipidemia."}, {"l": "Primer", "x": "Minimal change disease (tersering pada anak), FSGS, membranous nephropathy (tersering pada dewasa), MPGN."}, {"l": "Sekunder", "x": "DM, lupus, amiloidosis, infeksi (HBV, HCV, HIV), obat (NSAID), keganasan."}], "src": "(KDIGO Glomerular Diseases Work Group, 2021; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Kerusakan podosit", "x": "Barier filtrasi glomerulus bocor sehingga protein lolos ke urin."}, {"l": "Edema", "x": "Hipoalbuminemia menurunkan tekanan onkotik (underfill) disertai retensi natrium primer di tubulus (overfill)."}, {"l": "Hiperlipidemia", "x": "Sintesis hati meningkat dan katabolisme lipid menurun."}, {"l": "Hiperkoagulasi dan infeksi", "x": "Hilangnya antitrombin III dan IgG melalui urin."}], "src": "(Kumar et al., 2023; Loscalzo et al., 2022)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Edema", "x": "Periorbital pagi hari hingga anasarka, asites, efusi pleura."}, {"l": "Urin berbusa", "x": "Akibat proteinuria berat; produksi urin dapat berkurang."}, {"l": "Hipertensi dan hematuria", "x": "Umumnya tidak menonjol pada MCD; lebih sering pada FSGS/MPGN."}], "src": "(Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Urin", "x": "Urinalisis dan rasio protein/kreatinin urin (atau tampung 24 jam)."}, {"l": "Darah", "x": "Albumin, kolesterol/trigliserida, ureum/kreatinin."}, {"l": "Serologi", "x": "ANA, anti-dsDNA, C3/C4, HBsAg, anti-HCV, HIV, anti-PLA2R (membranous)."}, {"l": "Biopsi", "x": "Dewasa umumnya; anak bila usia <1 atau >12 tahun, hematuria/hipertensi menetap, atau resisten steroid."}], "src": "(KDIGO Glomerular Diseases Work Group, 2021)"}, {"t": "Tatalaksana", "items": [{"l": "Umum", "x": "Diet rendah garam, diuretik loop, ACEi/ARB (antiproteinuria), statin bila perlu."}, {"l": "MCD anak", "x": "Prednison dosis penuh harian 4–6 minggu lalu selang hari 4–6 minggu (total ≥12 minggu)."}, {"l": "Dewasa", "x": "MCD/FSGS: glukokortikoid; membranous: sesuai risiko (rituximab, inhibitor kalsineurin, siklofosfamid)."}, {"l": "Relaps/dependen steroid", "x": "Hemat steroid: levamisol, siklofosfamid, MMF, rituximab, inhibitor kalsineurin."}], "src": "(KDIGO Glomerular Diseases Work Group, 2021)"}, {"t": "Komplikasi", "items": [{"l": "Infeksi", "x": "Peritonitis spontan, selulitis, sepsis pneumokokus."}, {"l": "Tromboemboli", "x": "Terutama trombosis vena renalis."}, {"l": "AKI dan aterosklerosis dini", "x": "Akibat hipovolemia dan dislipidemia."}, {"l": "Efek samping terapi", "x": "Cushingoid, hipertensi, gangguan tumbuh anak."}], "src": "(Kumar et al., 2023; KDIGO Glomerular Diseases Work Group, 2021)"}]}, {"id": 4, "judul": "Nefropati IgA (Penyakit Berger)", "kat": "Nefrologi", "ciri": "Hematuria makroskopik 1–3 hari setelah ISPA (synpharyngitic); biopsi: deposit IgA mesangial; C3 normal.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "IgAN", "x": "Glomerulonefritis primer tersering di dunia; ditandai deposit IgA dominan di mesangium."}, {"l": "Mekanisme", "x": "IgA1 defisien galaktosa meningkat, memicu autoantibodi dan kompleks imun yang menumpuk di mesangium."}, {"l": "Pemicu", "x": "Infeksi saluran napas atas atau saluran cerna; bentuk sekunder pada sirosis, IBD, penyakit celiac, HIV."}], "src": "(KDIGO IgAN and IgAV Work Group, 2025; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Kompleks imun", "x": "Deposit IgA1 memicu proliferasi sel mesangial dan produksi sitokin."}, {"l": "Komplemen", "x": "Aktivasi jalur lektin/alternatif memperberat cedera glomerulus."}, {"l": "Skor Oxford (MEST-C)", "x": "Hiperselularitas Mesangial, proliferasi Endokapiler, sklerosis Segmental, atrofi Tubulus/fibrosis interstisial, Crescent."}], "src": "(KDIGO IgAN and IgAV Work Group, 2025; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Hematuria makroskopik berulang", "x": "Muncul 1–3 hari setelah ISPA (beda dengan GNAPS yang laten 1–3 minggu)."}, {"l": "Asimtomatik", "x": "Hematuria mikroskopik ± proteinuria saat pemeriksaan rutin."}, {"l": "Progresif", "x": "Hipertensi dan CKD; sindrom nefrotik atau RPGN jarang."}], "src": "(Loscalzo et al., 2022; KDIGO IgAN and IgAV Work Group, 2025)"}, {"t": "Diagnosis", "items": [{"l": "Urin dan fungsi ginjal", "x": "Urinalisis, rasio protein/kreatinin atau albumin/kreatinin, eGFR."}, {"l": "Biopsi ginjal", "x": "Baku emas: IF dominan IgA mesangial ± C3."}, {"l": "Komplemen", "x": "C3 normal (pembeda dari GNAPS dan lupus)."}, {"l": "Singkirkan sekunder", "x": "Sirosis hati, IgA vasculitis (HSP)."}], "src": "(KDIGO IgAN and IgAV Work Group, 2025)"}, {"t": "Tatalaksana", "items": [{"l": "Suportif optimal", "x": "ACEi/ARB dosis maksimal yang ditoleransi, kontrol tekanan darah, SGLT2i, diet, berhenti merokok, kendalikan berat badan."}, {"l": "Risiko progresi tinggi", "x": "Terapi tambahan yang menargetkan produksi IgA dan cedera imun (mis. budesonide rilis-target, sparsentan, penghambat komplemen); ketersediaan di Indonesia terbatas."}, {"l": "Glukokortikoid sistemik", "x": "Digunakan selektif karena efek samping bermakna."}, {"l": "Gagal ginjal", "x": "Terapi pengganti ginjal atau transplantasi (penyakit dapat kambuh di graft)."}], "src": "(KDIGO IgAN and IgAV Work Group, 2025)"}, {"t": "Komplikasi", "items": [{"l": "CKD/ESKD", "x": "Progresi lambat selama puluhan tahun pada sebagian pasien."}, {"l": "Hipertensi", "x": "Akibat penurunan fungsi nefron."}, {"l": "AKI", "x": "Akibat hematuria makroskopik (silinder eritrosit) atau RPGN."}], "src": "(KDIGO IgAN and IgAV Work Group, 2025; Kumar et al., 2023)"}]}, {"id": 5, "judul": "Nefritis Lupus", "kat": "Nefrologi", "ciri": "Keterlibatan ginjal pada SLE; kelas IV paling sering/berat; C3-C4 turun, anti-dsDNA positif, full-house IF.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Nefritis lupus", "x": "Glomerulonefritis imun pada SLE; salah satu manifestasi organ paling serius."}, {"l": "Klasifikasi ISN/RPS", "x": "I mesangial minimal, II proliferatif mesangial, III fokal, IV difus, V membranosa, VI sklerosis lanjut."}, {"l": "Kelas proliferatif", "x": "Kelas III dan IV paling berat dan memerlukan imunosupresi agresif."}], "src": "(KDIGO Lupus Nephritis Work Group, 2024; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Kompleks imun", "x": "Anti-dsDNA membentuk kompleks yang terdeposit subendotel (proliferatif) atau subepitel (membranosa)."}, {"l": "Komplemen", "x": "Aktivasi jalur klasik menurunkan C3 dan C4."}, {"l": "Patologi khas", "x": "Wire-loop lesion dan pola full-house IF (IgG, IgA, IgM, C3, C1q)."}], "src": "(Kumar et al., 2023; KDIGO Lupus Nephritis Work Group, 2024)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Ginjal", "x": "Proteinuria hingga sindrom nefrotik, hematuria, hipertensi, penurunan LFG."}, {"l": "Ekstrarenal SLE", "x": "Ruam malar, fotosensitivitas, artritis, ulkus oral, sitopenia."}], "src": "(Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Serologi", "x": "ANA, anti-dsDNA, anti-Sm; C3 dan C4 rendah."}, {"l": "Urin", "x": "Sedimen aktif, rasio protein/kreatinin urin."}, {"l": "Biopsi ginjal", "x": "Dianjurkan pada proteinuria ≥0,5 g/hari dengan hematuria/silinder; menentukan kelas serta aktivitas dan kronisitas."}], "src": "(KDIGO Lupus Nephritis Work Group, 2024)"}, {"t": "Tatalaksana", "items": [{"l": "Semua pasien", "x": "Hidroksiklorokuin, ACEi/ARB, kontrol tekanan darah."}, {"l": "Kelas III/IV (± V)", "x": "Induksi glukokortikoid + salah satu: mikofenolat, siklofosfamid IV dosis rendah, belimumab + mikofenolat/siklofosfamid, atau mikofenolat + inhibitor kalsineurin (voklosporin/takrolimus)."}, {"l": "Pemeliharaan", "x": "Mikofenolat atau azatioprin, umumnya ≥3 tahun, dengan tapering steroid."}], "src": "(KDIGO Lupus Nephritis Work Group, 2024)"}, {"t": "Komplikasi", "items": [{"l": "CKD/ESKD", "x": "Terutama kelas proliferatif yang tidak terkontrol."}, {"l": "Infeksi", "x": "Akibat imunosupresi."}, {"l": "Toksisitas obat", "x": "Teratogenik (mikofenolat, siklofosfamid), infertilitas siklofosfamid."}, {"l": "Kardiovaskular", "x": "Risiko aterosklerosis dini."}], "src": "(KDIGO Lupus Nephritis Work Group, 2024; Kumar et al., 2023)"}]}, {"id": 6, "judul": "Cedera Ginjal Akut (Acute Kidney Injury/AKI)", "kat": "Nefrologi", "ciri": "Kreatinin naik ≥0,3 mg/dL dalam 48 jam, atau ≥1,5× baseline dalam 7 hari, atau urin <0,5 mL/kg/jam selama 6 jam.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Kriteria KDIGO", "x": "Kenaikan kreatinin ≥0,3 mg/dL dalam 48 jam, atau ≥1,5× nilai dasar dalam 7 hari, atau urin <0,5 mL/kg/jam selama ≥6 jam."}, {"l": "Stadium", "x": "1: 1,5–1,9× atau ≥0,3 mg/dL; 2: 2,0–2,9×; 3: ≥3× atau kreatinin ≥4 mg/dL atau mulai dialisis (urin <0,3 mL/kg/jam ≥24 jam atau anuria ≥12 jam)."}, {"l": "Prerenal", "x": "Hipovolemia, syok, gagal jantung, sirosis; diperberat NSAID/ACEi/ARB."}, {"l": "Intrarenal", "x": "ATN (iskemik, toksik: aminoglikosida, kontras, rabdomiolisis), nefritis interstisial akut, GN akut, vaskulitis."}, {"l": "Postrenal", "x": "Obstruksi (BPH, batu, tumor, kateter tersumbat)."}], "src": "(KDIGO AKI Work Group, 2012)"}, {"t": "Patofisiologi", "items": [{"l": "Prerenal", "x": "Perfusi turun sehingga LFG turun, tubulus masih utuh; reabsorpsi Na dan urea meningkat."}, {"l": "ATN", "x": "Iskemia/toksin menyebabkan nekrosis sel tubulus, sumbatan silinder, backleak filtrat, dan vasokonstriksi intrarenal."}, {"l": "Fase ATN", "x": "Inisiasi, ekstensi, pemeliharaan (oliguria 1–2 minggu), pemulihan (poliuria)."}, {"l": "Postrenal", "x": "Tekanan intratubular naik menurunkan LFG."}], "src": "(Kumar et al., 2023; Loscalzo et al., 2022)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Urin", "x": "Oliguria (<400 mL/hari) atau non-oliguria."}, {"l": "Overload cairan", "x": "Edema, sesak, hipertensi."}, {"l": "Uremia", "x": "Mual, anoreksia, pruritus, ensefalopati, perikarditis."}, {"l": "Hiperkalemia", "x": "Kelemahan otot hingga aritmia."}], "src": "(Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Lab", "x": "Ureum, kreatinin, elektrolit (K), analisa gas darah."}, {"l": "Indeks", "x": "Prerenal: FENa <1%, rasio BUN/kreatinin >20; ATN: FENa >2%, silinder granular muddy brown."}, {"l": "Pencitraan", "x": "USG ginjal menilai obstruksi dan ukuran ginjal."}, {"l": "Evaluasi etiologi", "x": "Riwayat obat, hipovolemia, urinalisis, serologi bila dicurigai GN."}], "src": "(KDIGO AKI Work Group, 2012; Loscalzo et al., 2022)"}, {"t": "Tatalaksana", "items": [{"l": "Penyebab", "x": "Resusitasi cairan kristaloid bila hipovolemik; hindari nefrotoksin; drainase bila obstruksi."}, {"l": "Hiperkalemia", "x": "Kalsium glukonat (stabilisasi membran), insulin + dekstrosa, β2-agonis, diuretik loop/resin pengikat kalium."}, {"l": "Indikasi dialisis", "x": "Asidosis berat refrakter, hiperkalemia refrakter, overload cairan refrakter, intoksikasi dialisabel, komplikasi uremia (perikarditis, ensefalopati)."}, {"l": "Penyesuaian obat", "x": "Dosis obat disesuaikan dengan fungsi ginjal."}], "src": "(KDIGO AKI Work Group, 2012; Loscalzo et al., 2022)"}, {"t": "Komplikasi", "items": [{"l": "Metabolik", "x": "Hiperkalemia, asidosis metabolik, hiperfosfatemia, hipokalsemia."}, {"l": "Kardiopulmoner", "x": "Edema paru, aritmia."}, {"l": "Jangka panjang", "x": "Infeksi, progresi ke CKD."}], "src": "(KDIGO AKI Work Group, 2012; KDIGO CKD Work Group, 2024)"}]}, {"id": 7, "judul": "Penyakit Ginjal Kronik (PGK/CKD)", "kat": "Nefrologi", "ciri": "Kelainan ginjal atau LFG <60 mL/menit/1,73 m² selama >3 bulan; klasifikasi G1–G5 dan A1–A3.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "CKD", "x": "Kelainan struktur/fungsi ginjal yang menetap >3 bulan: eGFR <60 mL/menit/1,73 m² atau penanda kerusakan (UACR ≥30 mg/g, sedimen abnormal, kelainan struktur, riwayat transplantasi)."}, {"l": "Stadium LFG", "x": "G1 ≥90; G2 60–89; G3a 45–59; G3b 30–44; G4 15–29; G5 <15 (gagal ginjal)."}, {"l": "Stadium albuminuria", "x": "A1 <30; A2 30–300; A3 >300 mg/g."}, {"l": "Etiologi", "x": "DM, hipertensi, glomerulonefritis kronik, ADPKD, uropati obstruktif, nefritis interstisial kronik, obat nefrotoksik."}], "src": "(KDIGO CKD Work Group, 2024)"}, {"t": "Patofisiologi", "items": [{"l": "Hilangnya nefron", "x": "Nefron tersisa mengalami hiperfiltrasi dan hipertensi intraglomerulus."}, {"l": "Sklerosis glomerulus", "x": "Hiperfiltrasi menimbulkan kerusakan lanjut (lingkaran setan)."}, {"l": "RAAS", "x": "Aktivasi RAAS memperberat hipertensi, proteinuria, dan fibrosis."}, {"l": "Fibrosis tubulointerstisial", "x": "Jalur akhir bersama berbagai penyebab CKD."}], "src": "(Kumar et al., 2023; Loscalzo et al., 2022)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Awal", "x": "Sering asimtomatik atau nokturia."}, {"l": "Uremia", "x": "Lemas, anoreksia, mual, pruritus, ensefalopati, perikarditis uremik."}, {"l": "Edema dan hipertensi", "x": "Akibat retensi natrium dan air."}, {"l": "Pucat", "x": "Akibat anemia."}], "src": "(Loscalzo et al., 2022; Setiati et al., 2014)"}, {"t": "Diagnosis", "items": [{"l": "eGFR dan UACR", "x": "Hitung eGFR dari kreatinin (CKD-EPI) dan ukur albuminuria; ulangi untuk memastikan kronisitas >3 bulan."}, {"l": "USG", "x": "Ginjal mengecil dengan ekogenisitas meningkat (kecuali DM, ADPKD, amiloid)."}, {"l": "Cari penyebab", "x": "Urinalisis/sedimen, riwayat DM-hipertensi, serologi, biopsi bila perlu."}, {"l": "Komplikasi", "x": "Hb, kalsium, fosfat, PTH, bikarbonat, kalium."}], "src": "(KDIGO CKD Work Group, 2024)"}, {"t": "Tatalaksana", "items": [{"l": "Proteksi ginjal", "x": "ACEi/ARB pada albuminuria, SGLT2i (eGFR ≥20), finerenone pada DM tipe 2 dengan albuminuria, kontrol tekanan darah (target sistolik <120 mmHg bila ditoleransi dengan pengukuran terstandar)."}, {"l": "Diet", "x": "Protein sekitar 0,8 g/kgBB/hari, natrium <2 g/hari; hindari restriksi protein berlebihan."}, {"l": "Komplikasi", "x": "ESA dan besi untuk anemia, pengikat fosfat dan vitamin D untuk gangguan mineral-tulang, bikarbonat untuk asidosis."}, {"l": "Terapi pengganti ginjal", "x": "Hemodialisis, dialisis peritoneal, transplantasi; dimulai berdasarkan gejala/komplikasi, bukan angka eGFR semata."}, {"l": "Hindari nefrotoksin", "x": "NSAID, kontras tanpa persiapan, aminoglikosida; vaksinasi."}], "src": "(KDIGO CKD Work Group, 2024; KDIGO Diabetes Work Group, 2022)"}, {"t": "Komplikasi", "items": [{"l": "Kardiovaskular", "x": "Penyebab kematian utama."}, {"l": "Anemia", "x": "Defisiensi eritropoietin."}, {"l": "Gangguan mineral-tulang", "x": "Hiperfosfatemia, hipokalsemia, hiperparatiroidisme sekunder."}, {"l": "Metabolik", "x": "Asidosis metabolik, hiperkalemia."}], "src": "(KDIGO CKD Work Group, 2024; Loscalzo et al., 2022)"}]}, {"id": 8, "judul": "Penyakit Ginjal Diabetik (Nefropati Diabetik)", "kat": "Nefrologi", "ciri": "Albuminuria persisten pada pasien DM; lesi Kimmelstiel–Wilson (glomerulosklerosis nodular).", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Penyakit ginjal diabetik", "x": "Albuminuria persisten (UACR ≥30 mg/g) dan/atau eGFR <60 pada pasien DM tanpa penyebab lain."}, {"l": "Epidemiologi", "x": "Penyebab utama penyakit ginjal tahap akhir di banyak negara."}, {"l": "Faktor risiko", "x": "Hiperglikemia kronik, hipertensi, durasi DM, merokok, obesitas, genetik."}], "src": "(KDIGO Diabetes Work Group, 2022; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Jalur metabolik", "x": "Hiperglikemia memicu AGEs, jalur poliol, aktivasi PKC, dan stres oksidatif."}, {"l": "Hemodinamik", "x": "Dilatasi arteriol aferen dan aktivasi RAAS menyebabkan hiperfiltrasi glomerulus."}, {"l": "Histologi", "x": "Penebalan membran basal glomerulus, ekspansi mesangial, nodul Kimmelstiel–Wilson, hialinosis arteriol."}, {"l": "Stadium (Mogensen)", "x": "1 hiperfiltrasi, 2 silent, 3 mikroalbuminuria (30–300 mg/g), 4 makroalbuminuria (>300), 5 gagal ginjal."}], "src": "(Kumar et al., 2023; Loscalzo et al., 2022)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Awal", "x": "Asimtomatik; terdeteksi dari albuminuria."}, {"l": "Lanjut", "x": "Urin berbusa, edema, hipertensi, tanda uremia."}, {"l": "Komorbid", "x": "Sering disertai retinopati dan neuropati diabetik."}], "src": "(Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Skrining", "x": "UACR dan eGFR tahunan (DM tipe 2 sejak diagnosis; DM tipe 1 setelah ±5 tahun)."}, {"l": "Konfirmasi", "x": "Albuminuria abnormal pada ≥2 dari 3 sampel dalam 3–6 bulan."}, {"l": "Biopsi", "x": "Bila atipikal: hematuria bermakna, tanpa retinopati, atau LFG turun cepat."}], "src": "(KDIGO Diabetes Work Group, 2022)"}, {"t": "Tatalaksana", "items": [{"l": "Glikemik", "x": "Target HbA1c individual (kira-kira 6,5% hingga <8%)."}, {"l": "Proteksi ginjal", "x": "ACEi/ARB, SGLT2i (eGFR ≥20), finerenone, GLP-1 RA bila target glikemik belum tercapai."}, {"l": "Metformin", "x": "Dapat dipakai bila eGFR ≥30; sesuaikan dosis."}, {"l": "Kardiovaskular", "x": "Statin, kontrol tekanan darah, berhenti merokok."}], "src": "(KDIGO Diabetes Work Group, 2022)"}, {"t": "Komplikasi", "items": [{"l": "ESKD", "x": "Memerlukan dialisis atau transplantasi."}, {"l": "Kardiovaskular", "x": "Risiko sangat tinggi."}, {"l": "Hiperkalemia dan hipoglikemia", "x": "Klirens insulin menurun pada CKD."}], "src": "(KDIGO Diabetes Work Group, 2022; KDIGO CKD Work Group, 2024)"}]}, {"id": 9, "judul": "Penyakit Ginjal Polikistik Dominan Autosom (ADPKD)", "kat": "Nefrologi", "ciri": "Kista bilateral multipel, mutasi PKD1/PKD2, hipertensi, kista hati, aneurisma intrakranial.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "ADPKD", "x": "Kelainan monogenik pewarisan autosom dominan; penyebab genetik tersering gagal ginjal."}, {"l": "Gen", "x": "PKD1 (tersering, perjalanan lebih berat) dan PKD2 (lebih ringan); gen minor lain (mis. DNAJB11)."}, {"l": "Epidemiologi", "x": "Sekitar 5–10% pasien gagal ginjal di dunia."}], "src": "(KDIGO ADPKD Work Group, 2025; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Sistogenesis", "x": "Defek polisistin/silia primer menyebabkan proliferasi epitel tubulus, sekresi cairan (jalur cAMP), dan pembentukan kista."}, {"l": "Perjalanan", "x": "Kista membesar, parenkim normal tertekan, LFG turun bertahap."}, {"l": "Faktor progresi", "x": "Genotipe (PKD1 truncating), jenis kelamin laki-laki, hipertensi, total kidney volume besar."}], "src": "(KDIGO ADPKD Work Group, 2025)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Ginjal", "x": "Nyeri pinggang, hematuria, ISK, batu, hipertensi."}, {"l": "Ekstrarenal", "x": "Kista hati, aneurisma intrakranial, prolaps katup mitral, divertikulosis, hernia."}, {"l": "Fungsi ginjal", "x": "Sering baik hingga usia dekade ketiga-keempat, lalu menurun."}], "src": "(KDIGO ADPKD Work Group, 2025; Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "USG (kriteria Pei–Ravine)", "x": "Usia 15–39: ≥3 kista (uni/bilateral); 40–59: ≥2 kista tiap ginjal; ≥60: ≥4 kista tiap ginjal; pada usia ≥40, <2 kista menyingkirkan ADPKD."}, {"l": "MRI/CT dan genetik", "x": "Untuk kasus atipikal atau tanpa riwayat keluarga."}, {"l": "Prognosis", "x": "Total kidney volume dan skor PROPKD membantu menilai risiko progresi cepat."}], "src": "(KDIGO ADPKD Work Group, 2025)"}, {"t": "Tatalaksana", "items": [{"l": "Hipertensi", "x": "ACEi/ARB sebagai pilihan utama."}, {"l": "Hidrasi dan diet", "x": "Asupan cairan cukup, natrium rendah, kendalikan berat badan."}, {"l": "Tolvaptan", "x": "Dipertimbangkan pada pasien dengan risiko progresi cepat; pantau fungsi hati."}, {"l": "Infeksi kista", "x": "Antibiotik ±4–6 minggu; gagal ginjal: dialisis/transplantasi."}], "src": "(KDIGO ADPKD Work Group, 2025)"}, {"t": "Komplikasi", "items": [{"l": "Infeksi dan perdarahan kista", "x": "Nyeri akut, demam, hematuria."}, {"l": "Aneurisma intrakranial", "x": "Risiko perdarahan subaraknoid; skrining pada riwayat keluarga."}, {"l": "ESKD", "x": "Memerlukan terapi pengganti ginjal."}], "src": "(KDIGO ADPKD Work Group, 2025; Loscalzo et al., 2022) BAGIAN B — UROLOGI (Saluran Kemih & Genitalia Pria)"}]}, {"id": 10, "judul": "Urolitiasis (Batu Ginjal, Ureter, Buli)", "kat": "Urologi", "ciri": "Kolik pinggang menjalar ke inguinal + hematuria; CT non-kontras dosis rendah; obstruksi + infeksi = emergensi.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Urolitiasis", "x": "Batu pada saluran kemih: nefrolitiasis, ureterolitiasis, vesikolitiasis, uretrolitiasis."}, {"l": "Komposisi", "x": "Kalsium oksalat (±80%), kalsium fosfat, asam urat (radiolusen), struvit (infeksi), sistin (herediter)."}, {"l": "Faktor risiko", "x": "Dehidrasi, diet tinggi natrium/protein hewani/oksalat, hiperkalsiuria, hiperurisemia, ISK urease, hiperparatiroidisme, obesitas/DM, riwayat keluarga."}], "src": "(EAU, 2026a; McAninch & Lue, 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Supersaturasi", "x": "Urin jenuh zat pembentuk batu menyebabkan nukleasi, pertumbuhan, dan agregasi kristal."}, {"l": "Inhibitor", "x": "Sitrat dan magnesium yang rendah memudahkan pembentukan batu."}, {"l": "Struvit", "x": "Urease kuman (Proteus) menaikkan pH dan amonia sehingga terbentuk magnesium-amonium-fosfat; dapat menjadi staghorn."}, {"l": "Asam urat", "x": "Terbentuk pada urin pH asam (<5,5)."}], "src": "(EAU, 2026a; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Kolik renal", "x": "Nyeri pinggang hebat mendadak, hilang timbul, menjalar ke inguinal/genital."}, {"l": "Penyerta", "x": "Mual-muntah, gelisah (tidak bisa diam), hematuria."}, {"l": "Batu ureter distal/buli", "x": "Disuria, frekuensi, urgensi; batu buli: pancar terputus."}, {"l": "Asimtomatik", "x": "Batu ginjal besar atau staghorn bisa tanpa gejala."}], "src": "(EAU, 2026a; McAninch & Lue, 2020)"}, {"t": "Diagnosis", "items": [{"l": "Urinalisis", "x": "Hematuria; kultur bila curiga ISK."}, {"l": "CT non-kontras dosis rendah", "x": "Pencitraan pilihan pada nyeri pinggang akut."}, {"l": "USG + foto polos (BNO/KUB)", "x": "Alternatif; USG utama pada anak dan ibu hamil."}, {"l": "Lab dan metabolik", "x": "Kreatinin, kalsium, asam urat; analisis batu; urin 24 jam pada risiko tinggi."}], "src": "(EAU, 2026a)"}, {"t": "Tatalaksana", "items": [{"l": "Kolik", "x": "NSAID (diklofenak/ketorolak) lini pertama; opioid bila gagal."}, {"l": "Batu kecil", "x": "Observasi dan terapi ekspulsi medik (α-blocker, mis. tamsulosin) pada batu ureter distal."}, {"l": "Intervensi", "x": "ESWL (batu ginjal ≤20 mm), URS/RIRS (ureter, ginjal), PCNL (>20 mm/staghorn), litotripsi endoskopik atau sistolitotomi (batu buli)."}, {"l": "Emergensi", "x": "Obstruksi + infeksi/sepsis: dekompresi dulu (stent DJ atau nefrostomi), batu ditangani belakangan."}, {"l": "Pencegahan", "x": "Diuresis ≥2,5 L/hari, kalsium diet normal, natrium dan protein hewani rendah; sitrat, tiazid, alopurinol, alkalinisasi urin sesuai jenis batu."}], "src": "(EAU, 2026a)"}, {"t": "Komplikasi", "items": [{"l": "Hidronefrosis dan gagal ginjal", "x": "Akibat obstruksi."}, {"l": "Infeksi", "x": "Pielonefritis, pionefrosis, urosepsis."}, {"l": "Pascatindakan", "x": "Striktur ureter, batu impaksi."}, {"l": "Rekurensi", "x": "Tinggi (kira-kira separuh dalam 10 tahun)."}], "src": "(EAU, 2026a)"}]}, {"id": 11, "judul": "Hidronefrosis & Uropati Obstruktif", "kat": "Urologi", "ciri": "Dilatasi pelvis-kaliks akibat obstruksi aliran urin; USG pilihan pertama; dekompresi bila infeksi/anuria.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Hidronefrosis", "x": "Pelebaran pelvis dan kaliks ginjal karena hambatan aliran urin; uropati obstruktif = kerusakan akibat obstruksi tersebut."}, {"l": "Intralumen", "x": "Batu, bekuan darah."}, {"l": "Dinding", "x": "Striktur, obstruksi pelviureter (PUJ), tumor urotel, buli neurogenik."}, {"l": "Eksternal", "x": "BPH, kanker prostat/serviks, fibrosis retroperitoneal, kehamilan."}], "src": "(Partin et al., 2020; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Tekanan meningkat", "x": "Tekanan intratubular naik, LFG turun."}, {"l": "Atrofi", "x": "Parenkim menipis dan ginjal mengalami kerusakan permanen bila berkepanjangan."}, {"l": "Obstruksi bawah", "x": "Dapat bilateral (BPH, striktur uretra, buli neurogenik)."}, {"l": "Setelah dekompresi", "x": "Dapat terjadi diuresis pascaobstruksi."}], "src": "(Kumar et al., 2023; Partin et al., 2020)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Nyeri", "x": "Nyeri/kolik pinggang atau massa pinggang."}, {"l": "ISK", "x": "ISK berulang atau demam."}, {"l": "Obstruksi total/bilateral", "x": "Oligo-anuria, AKI/CKD."}], "src": "(Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "USG", "x": "Pilihan pertama: dilatasi kaliks, penipisan korteks."}, {"l": "CT/CT urografi", "x": "Menentukan penyebab."}, {"l": "Renografi nuklir (MAG3)", "x": "Menilai fungsi dan obstruksi (mis. PUJ)."}, {"l": "Obstruksi bawah", "x": "Ukur residu pasca berkemih; kateter buli."}], "src": "(Partin et al., 2020)"}, {"t": "Tatalaksana", "items": [{"l": "Dekompresi", "x": "Obstruksi bawah: kateter uretra/suprapubik; obstruksi atas: stent DJ atau nefrostomi perkutan."}, {"l": "Definitif", "x": "Tangani penyebab (batu, BPH, striktur); pieloplasti pada obstruksi PUJ."}, {"l": "Pantau", "x": "Diuresis pascaobstruksi dan elektrolit."}], "src": "(Partin et al., 2020; EAU, 2026a)"}, {"t": "Komplikasi", "items": [{"l": "Infeksi", "x": "Pionefrosis dan urosepsis."}, {"l": "Gagal ginjal", "x": "AKI/CKD."}, {"l": "Lain", "x": "Batu sekunder, hipertensi."}], "src": "(Partin et al., 2020)"}]}, {"id": 12, "judul": "Benign Prostatic Hyperplasia (BPH)", "kat": "Urologi", "ciri": "Pria >50 tahun, LUTS obstruktif + iritatif; hiperplasia zona transisional; TURP baku emas bedah.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "BPH", "x": "Pembesaran prostat jinak akibat hiperplasia stroma dan epitel zona transisional yang dapat menimbulkan LUTS."}, {"l": "Faktor", "x": "Usia dan androgen (DHT oleh 5α-reduktase tipe 2); estrogen berperan."}, {"l": "BPE dan BOO", "x": "Pembesaran prostat (BPE) dapat menimbulkan obstruksi infravesika (BOO)."}], "src": "(EAU, 2025c; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Komponen statis", "x": "Volume jaringan prostat yang membesar menekan uretra."}, {"l": "Komponen dinamis", "x": "Tonus otot polos prostat dan leher buli (reseptor α1)."}, {"l": "Akibat pada buli", "x": "Hipertrofi detrusor, trabekulasi, divertikel, instabilitas detrusor, dan akhirnya dekompensasi."}], "src": "(Kumar et al., 2023; Partin et al., 2020)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Voiding (obstruktif)", "x": "Pancar lemah, hesitancy, intermittency, mengejan, terminal dribbling, rasa tidak tuntas."}, {"l": "Storage (iritatif)", "x": "Frekuensi, urgensi, nokturia, urge incontinence."}, {"l": "IPSS", "x": "0–7 ringan, 8–19 sedang, 20–35 berat."}, {"l": "Komplikasi akut", "x": "Retensi urin akut."}], "src": "(EAU, 2025c; Lerner et al., 2021a)"}, {"t": "Diagnosis", "items": [{"l": "Anamnesis dan IPSS", "x": "Kuesioner gejala, riwayat obat."}, {"l": "Colok dubur (DRE)", "x": "Prostat membesar simetris, kenyal; nodul keras curiga keganasan."}, {"l": "Urinalisis dan PSA", "x": "Singkirkan ISK dan hematuria; PSA untuk menilai volume dan risiko keganasan."}, {"l": "USG dan uroflowmetri", "x": "Volume prostat, residu urin, Qmax <10 mL/detik sugestif obstruksi."}], "src": "(Lerner et al., 2021a; EAU, 2025c)"}, {"t": "Tatalaksana", "items": [{"l": "Watchful waiting", "x": "Gejala ringan: edukasi, modifikasi cairan/kafein, hindari obat pemicu."}, {"l": "α1-blocker", "x": "Tamsulosin, alfuzosin: perbaikan gejala cepat; efek samping hipotensi ortostatik, ejakulasi retrograd."}, {"l": "Inhibitor 5α-reduktase", "x": "Finasteride, dutasteride untuk volume prostat >30–40 mL; mengecilkan prostat dan menurunkan PSA ±50%."}, {"l": "Tambahan", "x": "Tadalafil 5 mg, antimuskarinik/β3-agonis bila dominan OAB, kombinasi α-blocker + 5-ARI."}, {"l": "Indikasi operasi", "x": "Retensi urin berulang, ISK berulang, batu buli, hematuria berulang, gangguan fungsi ginjal akibat BPH, divertikel, gagal terapi medik."}, {"l": "Pilihan operasi", "x": "TURP (baku emas), enukleasi laser (HoLEP), prostatektomi terbuka (prostat besar >80 mL), TUIP (prostat kecil)."}], "src": "(Lerner et al., 2021a; Lerner et al., 2021b; EAU, 2025c)"}, {"t": "Komplikasi", "items": [{"l": "Retensi urin akut/kronik", "x": "Termasuk overflow incontinence."}, {"l": "ISK dan batu buli", "x": "Akibat residu urin."}, {"l": "Hidronefrosis dan gagal ginjal", "x": "Obstruksi kronik."}, {"l": "Komplikasi TURP", "x": "Sindrom TUR (hiponatremia), perdarahan, striktur uretra, ejakulasi retrograd, inkontinensia."}], "src": "(Lerner et al., 2021b; Partin et al., 2020)"}]}, {"id": 13, "judul": "Retensi Urin", "kat": "Urologi", "ciri": "Tidak bisa berkemih + nyeri suprapubik (akut); BPH penyebab tersering; kateterisasi, awasi diuresis pascaobstruksi.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Retensi urin akut", "x": "Ketidakmampuan berkemih tiba-tiba, nyeri, buli teraba penuh."}, {"l": "Retensi kronik", "x": "Residu urin tinggi (>300 mL), sering tanpa nyeri; overflow incontinence."}, {"l": "Obstruktif", "x": "BPH, striktur uretra, batu, tumor, bekuan, fimosis, konstipasi."}, {"l": "Non-obstruktif", "x": "Obat (antikolinergik, simpatomimetik, opioid), neurogenik (lesi medula spinalis, neuropati DM), infeksi/inflamasi, pascaoperasi."}], "src": "(Partin et al., 2020; EAU, 2025c)"}, {"t": "Patofisiologi", "items": [{"l": "Obstruksi", "x": "Resistensi uretra melebihi tekanan detrusor."}, {"l": "Detrusor", "x": "Kontraktilitas buruk (underactive) atau gangguan koordinasi neurologis."}, {"l": "Tekanan balik", "x": "Buli penuh meningkatkan tekanan ke ureter dan ginjal."}], "src": "(Partin et al., 2020; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Akut", "x": "Nyeri suprapubik hebat, gelisah, tidak bisa berkemih; buli teraba dan nyeri."}, {"l": "Kronik", "x": "Pancar lemah, menetes, buli membesar tanpa nyeri."}], "src": "(Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "Pemeriksaan fisik", "x": "Palpasi/perkusi suprapubik, colok dubur, status neurologis."}, {"l": "Bladder scan/USG", "x": "Menilai volume dan residu."}, {"l": "Penunjang", "x": "Urinalisis, kreatinin, USG ginjal, evaluasi penyebab."}], "src": "(Partin et al., 2020; EAU, 2025c)"}, {"t": "Tatalaksana", "items": [{"l": "Dekompresi", "x": "Kateter uretra; bila gagal, kateter suprapubik."}, {"l": "Setelah BPH", "x": "α-blocker sebelum trial without catheter (TWOC)."}, {"l": "Awasi", "x": "Diuresis pascaobstruksi (>200 mL/jam selama 2 jam berturut-turut atau >3 L/24 jam), elektrolit, hematuria ex vacuo."}, {"l": "Definitif", "x": "Tangani penyebab (BPH, striktur, obat)."}], "src": "(Partin et al., 2020; Lerner et al., 2021a)"}, {"t": "Komplikasi", "items": [{"l": "Cedera ginjal", "x": "Hidronefrosis, AKI."}, {"l": "Infeksi dan batu", "x": "ISK, batu buli."}, {"l": "Kerusakan buli", "x": "Detrusor atoni, divertikel."}], "src": "(Partin et al., 2020)"}]}, {"id": 14, "judul": "Striktur Uretra", "kat": "Urologi", "ciri": "Penyempitan lumen uretra akibat spongiofibrosis; pancar lemah; diagnosis RUG/VCUG; uretroplasti untuk striktur panjang/rekuren.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Striktur uretra", "x": "Penyempitan lumen akibat fibrosis jaringan spons uretra (spongiofibrosis)."}, {"l": "Iatrogenik", "x": "Kateterisasi, instrumentasi/TURP."}, {"l": "Trauma", "x": "Straddle injury (bulbar); fraktur pelvis (uretra posterior)."}, {"l": "Inflamasi", "x": "Uretritis (gonore), lichen sclerosus (BXO); sebagian idiopatik."}], "src": "(EAU, 2025h; Partin et al., 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Jejas epitel", "x": "Cedera mukosa dan korpus spongiosum memicu fibrosis."}, {"l": "Obstruksi", "x": "Pancar urin menurun, tekanan buli naik, residu urin, ISK."}], "src": "(EAU, 2025h; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Pancar lemah/bercabang", "x": "Sering disertai spraying."}, {"l": "LUTS", "x": "Frekuensi, disuria, rasa tidak tuntas."}, {"l": "Komplikasi", "x": "ISK berulang, retensi urin, epididimitis."}], "src": "(EAU, 2025h)"}, {"t": "Diagnosis", "items": [{"l": "Uroflowmetri", "x": "Kurva datar (plateau)."}, {"l": "Uretrografi (RUG ± VCUG)", "x": "Menentukan lokasi dan panjang striktur."}, {"l": "Uretroskopi", "x": "Konfirmasi langsung."}, {"l": "Residu urin", "x": "Diukur dengan USG/bladder scan."}], "src": "(EAU, 2025h)"}, {"t": "Tatalaksana", "items": [{"l": "Dilatasi dan uretrotomi interna optik", "x": "Striktur bulbar pendek (<2 cm) primer; angka kekambuhan tinggi."}, {"l": "Uretroplasti", "x": "Striktur panjang atau rekuren (anastomosis atau graft mukosa bukal)."}, {"l": "Kateterisasi mandiri bersih berkala", "x": "Mencegah kekambuhan pada kasus tertentu."}, {"l": "Drainase sementara", "x": "Kateter suprapubik bila retensi akut dan kateter uretra gagal."}], "src": "(EAU, 2025h)"}, {"t": "Komplikasi", "items": [{"l": "Retensi urin", "x": "Akut atau kronik."}, {"l": "ISK/batu buli", "x": "Akibat residu urin."}, {"l": "Fistula/abses periuretra", "x": "Dapat terjadi pada striktur lama."}, {"l": "Hidronefrosis", "x": "Gangguan fungsi ginjal."}], "src": "(EAU, 2025h; Partin et al., 2020)"}]}, {"id": 15, "judul": "Prostatitis", "kat": "Urologi", "ciri": "Klasifikasi NIH I–IV; akut = demam + nyeri perineum + prostat nyeri (jangan dipijat); CP/CPPS tersering.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Klasifikasi NIH", "x": "I bakteri akut; II bakteri kronik; III CP/CPPS (IIIA inflamasi, IIIB non-inflamasi); IV inflamasi asimtomatik."}, {"l": "Kuman", "x": "Enterobacterales (E. coli) tersering; juga Enterococcus, Pseudomonas."}, {"l": "CP/CPPS", "x": "Nyeri panggul kronik tanpa infeksi bakteri; penyebab multifaktor."}], "src": "(EAU, 2026b; Partin et al., 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Refluks intraprostat", "x": "Urin terinfeksi masuk ke duktus prostat."}, {"l": "Infeksi asending", "x": "Dari uretra atau instrumentasi/biopsi."}, {"l": "Biofilm dan kalkuli", "x": "Menyebabkan infeksi persisten (bakteri kronik)."}], "src": "(EAU, 2026b; Partin et al., 2020)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Akut", "x": "Demam, menggigil, nyeri perineum/suprapubik, disuria, retensi urin, malaise."}, {"l": "Kronik", "x": "Nyeri panggul/perineum/ejakulasi ≥3 bulan, LUTS, disfungsi seksual."}, {"l": "Colok dubur", "x": "Akut: prostat nyeri, hangat, membengkak; jangan dipijat."}], "src": "(EAU, 2026b)"}, {"t": "Diagnosis", "items": [{"l": "Urinalisis dan kultur", "x": "Kultur urin pancar tengah; kultur darah pada sepsis."}, {"l": "Meares–Stamey (4 gelas)", "x": "Membedakan bakteri kronik dan CP/CPPS."}, {"l": "Pencitraan", "x": "USG transabdominal/TRUS bila curiga abses."}, {"l": "PSA", "x": "Dapat meningkat; tunda interpretasi."}], "src": "(EAU, 2026b)"}, {"t": "Tatalaksana", "items": [{"l": "Akut berat", "x": "Rawat inap, antibiotik IV (sefalosporin generasi 3, fluorokuinolon, aminoglikosida)."}, {"l": "Akut ringan/kronik bakteri", "x": "Fluorokuinolon atau TMP-SMX sesuai kultur; akut sekitar 2–4 minggu, kronik ≥4 minggu."}, {"l": "CP/CPPS", "x": "Terapi multimodal: α-blocker, NSAID, fisioterapi dasar panggul, atasi aspek psikologis."}, {"l": "Retensi", "x": "Kateter suprapubik lebih baik pada prostatitis akut."}], "src": "(EAU, 2026b)"}, {"t": "Komplikasi", "items": [{"l": "Abses prostat", "x": "Perlu drainase."}, {"l": "Sepsis", "x": "Terutama prostatitis akut."}, {"l": "Retensi urin dan epididimitis", "x": "Akibat inflamasi/infeksi."}, {"l": "Prostatitis kronik", "x": "Berulang atau nyeri persisten."}], "src": "(EAU, 2026b; Partin et al., 2020)"}]}, {"id": 16, "judul": "Kanker Prostat", "kat": "Urologi", "ciri": "Adenokarsinoma zona perifer; DRE nodul keras, PSA meningkat; MRI sebelum biopsi; metastasis tulang osteoblastik.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Kanker prostat", "x": "Keganasan epitel prostat, >95% adenokarsinoma, terutama di zona perifer."}, {"l": "Faktor risiko", "x": "Usia, riwayat keluarga, mutasi BRCA2/BRCA1, etnis."}, {"l": "Skor Gleason/ISUP", "x": "Grade Group 1 (3+3), 2 (3+4), 3 (4+3), 4 (skor 8), 5 (skor 9–10)."}], "src": "(EAU, 2025e; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Ketergantungan androgen", "x": "Pertumbuhan awal bergantung androgen (target terapi ADT)."}, {"l": "Penyebaran", "x": "Lokal (kapsul, vesikula seminalis), kelenjar getah bening, tulang (osteoblastik)."}, {"l": "Progresi", "x": "Dapat menjadi resisten kastrasi."}], "src": "(EAU, 2025e; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Awal", "x": "Sering asimtomatik."}, {"l": "Lokal", "x": "LUTS obstruktif, hematuria, hematospermia."}, {"l": "Metastasis", "x": "Nyeri tulang, kompresi medula spinalis, anemia."}], "src": "(EAU, 2025e; Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "DRE dan PSA", "x": "Nodul keras, asimetris; PSA tinggi (ambang klasik 4 ng/mL, interpretasi disesuaikan usia dan volume)."}, {"l": "MRI multiparametrik", "x": "Sebelum biopsi (PI-RADS) untuk menentukan target."}, {"l": "Biopsi", "x": "Transperineal atau transrektal; histopatologi dengan Grade Group."}, {"l": "Staging", "x": "CT/MRI, bone scan atau PSMA-PET pada risiko menengah-tinggi."}], "src": "(EAU, 2025e)"}, {"t": "Tatalaksana", "items": [{"l": "Risiko rendah", "x": "Active surveillance atau terapi kuratif."}, {"l": "Lokal", "x": "Prostatektomi radikal atau radioterapi ± ADT jangka pendek/panjang."}, {"l": "Lanjut/metastasis", "x": "ADT (agonis/antagonis LHRH), ARPI (abiraterone, enzalutamide), docetaxel."}, {"l": "Paliatif", "x": "Radioterapi tulang, bifosfonat/denosumab."}], "src": "(EAU, 2025e)"}, {"t": "Komplikasi", "items": [{"l": "Metastasis tulang", "x": "Nyeri, fraktur patologis, kompresi medula spinalis."}, {"l": "Obstruksi saluran kemih", "x": "Hidronefrosis, gagal ginjal."}, {"l": "Efek terapi", "x": "Inkontinensia, disfungsi ereksi, efek ADT (osteoporosis, hot flush)."}], "src": "(EAU, 2025e)"}]}, {"id": 17, "judul": "Kanker Kandung Kemih", "kat": "Urologi", "ciri": "Hematuria total tanpa nyeri (painless); karsinoma urotel; faktor utama merokok; sistoskopi + TURBT.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Kanker buli", "x": "Terbanyak karsinoma urotel (>90%); NMIBC (Ta, T1, CIS) vs MIBC (≥T2)."}, {"l": "Faktor risiko", "x": "Merokok (utama), paparan amina aromatik (benzidin, 2-naftilamin), siklofosfamid, radiasi panggul."}, {"l": "Skistosomiasis", "x": "Schistosoma haematobium berkaitan dengan karsinoma sel skuamosa."}], "src": "(EAU, 2025b; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Jalur papiler", "x": "Tumor papiler low-grade, sering kambuh tetapi jarang invasif."}, {"l": "Jalur CIS/invasif", "x": "Lesi high-grade, CIS, risiko progresi tinggi."}, {"l": "Penyebaran", "x": "Invasi otot, kelenjar getah bening, hati, paru, tulang."}], "src": "(Kumar et al., 2023; EAU, 2025b)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Hematuria", "x": "Makroskopik total tanpa nyeri (painless), intermiten."}, {"l": "Gejala iritatif", "x": "Frekuensi, urgensi, disuria (terutama CIS)."}, {"l": "Lanjut", "x": "Nyeri panggul/pinggang (obstruksi ureter), massa, penurunan berat badan."}], "src": "(EAU, 2025b; Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "Sistoskopi + sitologi urin", "x": "Visualisasi tumor; sitologi untuk high-grade/CIS."}, {"l": "TURBT", "x": "Diagnosis histologis dan staging T; sertakan otot detrusor."}, {"l": "Pencitraan", "x": "CT urografi (saluran atas), CT/MRI untuk staging MIBC."}], "src": "(EAU, 2025b; EAU, 2025a)"}, {"t": "Tatalaksana", "items": [{"l": "NMIBC", "x": "TURBT + instilasi intravesika (mitomisin C/gemsitabin; BCG untuk risiko menengah-tinggi); re-TUR bila perlu."}, {"l": "MIBC", "x": "Sistektomi radikal dengan diversi urin + kemoterapi neoadjuvan berbasis cisplatin; alternatif trimodality (TURBT, kemoradiasi)."}, {"l": "Metastasis", "x": "Kemoterapi, imunoterapi, atau terapi target antibodi-obat."}, {"l": "Pemantauan", "x": "Sistoskopi berkala (kekambuhan tinggi pada NMIBC)."}], "src": "(EAU, 2025b; EAU, 2025a)"}, {"t": "Komplikasi", "items": [{"l": "Kekambuhan/progresi", "x": "Terutama NMIBC high-grade."}, {"l": "Obstruksi ureter", "x": "Hidronefrosis dan gagal ginjal."}, {"l": "Terapi", "x": "Efek BCG (sistitis, demam), komplikasi sistektomi, perdarahan."}], "src": "(EAU, 2025b; EAU, 2025a)"}]}, {"id": 18, "judul": "Karsinoma Sel Ginjal (RCC)", "kat": "Urologi", "ciri": "Clear cell terbanyak; trias klasik (hematuria, nyeri pinggang, massa) hanya minoritas; sindrom paraneoplastik.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "RCC", "x": "Keganasan epitel tubulus ginjal; clear cell 70–80%, lalu papiler dan kromofob."}, {"l": "Faktor risiko", "x": "Merokok, obesitas, hipertensi, penyakit ginjal tahap akhir/dialisis, ADPKD."}, {"l": "Genetik", "x": "Von Hippel–Lindau (mutasi VHL), tuberous sclerosis, Birt–Hogg–Dubé."}], "src": "(EAU, 2025f; Kumar et al., 2023)"}, {"t": "Patofisiologi", "items": [{"l": "Jalur VHL/HIF", "x": "Inaktivasi VHL meningkatkan HIF dan VEGF sehingga tumor sangat vaskular."}, {"l": "Penyebaran", "x": "Invasi vena renalis dan vena cava; metastasis paru, tulang, hati, otak."}, {"l": "Paraneoplastik", "x": "Produksi eritropoietin, PTHrP, renin."}], "src": "(Kumar et al., 2023; EAU, 2025f)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Trias klasik", "x": "Hematuria, nyeri pinggang, massa teraba (hanya minoritas)."}, {"l": "Paraneoplastik", "x": "Polisitemia, hiperkalsemia, hipertensi, sindrom Stauffer."}, {"l": "Lain", "x": "Varikokel kiri yang tidak mengecil saat berbaring, demam, penurunan berat badan; sebagian besar temuan insidental."}], "src": "(EAU, 2025f; Loscalzo et al., 2022)"}, {"t": "Diagnosis", "items": [{"l": "Pencitraan", "x": "CT/MRI kontras: massa padat yang menyangat kontras."}, {"l": "Staging", "x": "CT toraks-abdomen; bone scan/MRI otak bila ada gejala."}, {"l": "Biopsi", "x": "Selektif (massa kecil, terapi ablasi/sistemik)."}], "src": "(EAU, 2025f)"}, {"t": "Tatalaksana", "items": [{"l": "Lokal", "x": "Nefrektomi parsial (T1) atau radikal; ablasi atau active surveillance pada massa kecil."}, {"l": "Metastasis", "x": "Imunoterapi (kombinasi inhibitor checkpoint) ± TKI (sunitinib, pazopanib, axitinib)."}, {"l": "Sitoreduktif", "x": "Nefrektomi pada kasus terpilih."}, {"l": "Pemantauan", "x": "Follow-up berkala sesuai risiko."}], "src": "(EAU, 2025f)"}, {"t": "Komplikasi", "items": [{"l": "Perdarahan", "x": "Hematuria masif, ruptur tumor."}, {"l": "Trombus tumor", "x": "Vena renalis dan vena cava inferior."}, {"l": "Metastasis", "x": "Paru, tulang, hati, otak."}], "src": "(EAU, 2025f)"}]}, {"id": 19, "judul": "Torsio Testis", "kat": "Urologi", "ciri": "Emergensi: nyeri skrotum mendadak, testis tinggi-horizontal, refleks kremaster hilang; waktu emas ≤6 jam.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Torsio testis", "x": "Terpilinnya funiculus spermatikus sehingga aliran darah testis terputus."}, {"l": "Usia", "x": "Puncak pada neonatus dan remaja (12–18 tahun)."}, {"l": "Faktor anatomi", "x": "Bell-clapper deformity (tunika vaginalis melekat tinggi)."}], "src": "(Partin et al., 2020; EAU, 2025d)"}, {"t": "Patofisiologi", "items": [{"l": "Obstruksi vena lalu arteri", "x": "Edema, iskemia, lalu infark testis."}, {"l": "Waktu", "x": "Penyelamatan testis tinggi bila ≤6 jam; menurun tajam setelah 12–24 jam."}, {"l": "Cedera reperfusi", "x": "Dapat terjadi setelah detorsi."}], "src": "(Partin et al., 2020)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Nyeri", "x": "Mendadak, hebat, unilateral, di skrotum/inguinal."}, {"l": "Penyerta", "x": "Mual, muntah; tanpa gejala ISK."}, {"l": "Pemeriksaan", "x": "Testis tinggi dan horizontal, refleks kremaster hilang, Prehn negatif (nyeri tidak berkurang pada elevasi)."}], "src": "(Partin et al., 2020; EAU, 2025d)"}, {"t": "Diagnosis", "items": [{"l": "Klinis", "x": "Diagnosis utama; jangan menunda operasi untuk pencitraan."}, {"l": "Doppler USG", "x": "Aliran darah testis berkurang/hilang, bila tidak menunda tindakan."}], "src": "(Partin et al., 2020; EAU, 2025d)"}, {"t": "Tatalaksana", "items": [{"l": "Segera", "x": "Eksplorasi skrotum emergensi."}, {"l": "Detorsi manual", "x": "Dapat dilakukan sambil menyiapkan operasi (open-book)."}, {"l": "Operasi", "x": "Detorsi + orkidopeksi pada testis viabel; kontralateral difiksasi; orkiektomi bila nekrosis."}], "src": "(Partin et al., 2020; EAU, 2025d)"}, {"t": "Komplikasi", "items": [{"l": "Infark/atrofi testis", "x": "Hilangnya testis."}, {"l": "Infertilitas", "x": "Penurunan kualitas semen."}, {"l": "Abses skrotum", "x": "Pada testis nekrotik."}], "src": "(Partin et al., 2020)"}]}, {"id": 20, "judul": "Epididimitis & Orkitis", "kat": "Urologi", "ciri": "Nyeri skrotum bertahap; Prehn positif; <35 tahun = Chlamydia/Neisseria, >35 tahun = Enterobacterales; orkitis = mumps.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Epididimitis akut", "x": "Inflamasi epididimis (<6 minggu), sering disertai orkitis (epididimo-orkitis)."}, {"l": "Pria <35 tahun/aktif seksual", "x": "C. trachomatis dan N. gonorrhoeae."}, {"l": "Pria >35 tahun", "x": "Enterobacterales (E. coli), terkait obstruksi/BPH/instrumentasi."}, {"l": "Orkitis", "x": "Virus mumps (orkitis terisolasi), pasca parotitis."}], "src": "(EAU, 2026b; Workowski et al., 2021)"}, {"t": "Patofisiologi", "items": [{"l": "Infeksi asending", "x": "Dari uretra atau prostat melalui duktus deferens."}, {"l": "Refluks urin", "x": "Terinfeksi, terutama pada obstruksi."}, {"l": "Inflamasi", "x": "Edema, pembengkakan, dan nyeri epididimis."}], "src": "(EAU, 2026b; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Nyeri skrotum", "x": "Onset bertahap (bukan mendadak), unilateral, bengkak, eritema."}, {"l": "Penyerta", "x": "Demam, disuria, duh uretra."}, {"l": "Prehn", "x": "Positif: nyeri berkurang saat skrotum diangkat."}], "src": "(EAU, 2026b; Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "Urinalisis", "x": "Piuria; kultur urin; NAAT uretra untuk Chlamydia/Neisseria."}, {"l": "Doppler USG", "x": "Aliran meningkat pada epididimitis; menyingkirkan torsio dan abses."}, {"l": "Diferensial", "x": "Utamakan menyingkirkan torsio testis."}], "src": "(EAU, 2026b)"}, {"t": "Tatalaksana", "items": [{"l": "Penyebab IMS", "x": "Seftriakson 500 mg IM dosis tunggal + doksisiklin 100 mg 2×/hari selama 10 hari."}, {"l": "Penyebab enterik (>35 tahun)", "x": "Fluorokuinolon (mis. levofloksasin) sesuai kultur."}, {"l": "Suportif", "x": "Istirahat, elevasi skrotum, analgesik; pasangan seksual diterapi."}, {"l": "Orkitis mumps", "x": "Suportif."}], "src": "(Workowski et al., 2021; EAU, 2026b)"}, {"t": "Komplikasi", "items": [{"l": "Abses dan infark testis", "x": "Perlu drainase atau orkiektomi."}, {"l": "Infertilitas", "x": "Terutama bila bilateral."}, {"l": "Epididimitis kronik", "x": "Nyeri persisten."}], "src": "(EAU, 2026b; Partin et al., 2020)"}]}, {"id": 21, "judul": "Varikokel & Hidrokel", "kat": "Urologi", "ciri": "Varikokel = 'bag of worms', sisi kiri, bertambah saat Valsalva; hidrokel = transiluminasi positif.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Varikokel", "x": "Dilatasi pleksus pampiniformis; ±90% sisi kiri (vena testikularis kiri bermuara tegak lurus ke vena renalis)."}, {"l": "Varikokel unilateral kanan", "x": "Waspadai massa/obstruksi retroperitoneal."}, {"l": "Hidrokel", "x": "Cairan di antara lapisan tunika vaginalis; komunikans (processus vaginalis paten) pada anak."}], "src": "(Partin et al., 2020; EAU, 2025g)"}, {"t": "Patofisiologi", "items": [{"l": "Varikokel", "x": "Katup vena tidak kompeten dan refluks darah vena meningkatkan suhu skrotum."}, {"l": "Dampak", "x": "Spermatogenesis terganggu; penyebab infertilitas pria yang dapat diperbaiki."}, {"l": "Hidrokel", "x": "Produksi dan reabsorpsi cairan tidak seimbang."}], "src": "(Partin et al., 2020; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Varikokel", "x": "Rasa berat/nyeri tumpul, 'bag of worms', bertambah saat berdiri/Valsalva; derajat 1–3."}, {"l": "Hidrokel", "x": "Pembengkakan skrotum tak nyeri; membesar sepanjang hari bila komunikans."}], "src": "(Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "Varikokel", "x": "Pemeriksaan fisik berdiri + Valsalva; Doppler USG; analisis semen."}, {"l": "Hidrokel", "x": "Transiluminasi positif; USG bila massa tidak jelas."}], "src": "(Partin et al., 2020; EAU, 2025g)"}, {"t": "Tatalaksana", "items": [{"l": "Varikokel", "x": "Varikokelektomi/embolisasi bila infertilitas dengan semen abnormal, nyeri, atau atrofi testis pada anak."}, {"l": "Hidrokel bayi", "x": "Observasi (sering menghilang usia 1–2 tahun)."}, {"l": "Hidrokel dewasa/komunikans", "x": "Hidrokelektomi atau herniotomi."}], "src": "(Partin et al., 2020; EAU, 2025g)"}, {"t": "Komplikasi", "items": [{"l": "Varikokel", "x": "Infertilitas, atrofi testis."}, {"l": "Hidrokel", "x": "Infeksi, hematokel, hernia inguinalis bersamaan."}], "src": "(Partin et al., 2020)"}]}, {"id": 22, "judul": "Uretritis & Infeksi Menular Seksual Genitourinari", "kat": "Urologi", "ciri": "Gonokokal: duh purulen, diplokokus gram-negatif intrasel; non-gonokokal: Chlamydia, duh mukoid.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Uretritis gonokokal", "x": "N. gonorrhoeae; inkubasi 2–7 hari."}, {"l": "Uretritis non-gonokokal", "x": "C. trachomatis, Mycoplasma genitalium, Ureaplasma; inkubasi 1–3 minggu."}, {"l": "Faktor risiko", "x": "Hubungan seksual tanpa kondom, pasangan multipel."}], "src": "(Workowski et al., 2021; EAU, 2026b)"}, {"t": "Patofisiologi", "items": [{"l": "Infeksi mukosa", "x": "Kuman menempel dan menginvasi epitel uretra."}, {"l": "Penyebaran", "x": "Ke epididimis, prostat, atau saluran genital atas (wanita: PID)."}], "src": "(Workowski et al., 2021; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Gonokokal", "x": "Duh uretra purulen banyak, disuria berat."}, {"l": "Non-gonokokal", "x": "Duh mukoid/jernih, disuria ringan; sering asimtomatik."}, {"l": "Wanita", "x": "Sering asimtomatik; servisitis, nyeri panggul."}], "src": "(Workowski et al., 2021; Partin et al., 2020)"}, {"t": "Diagnosis", "items": [{"l": "Pewarnaan Gram", "x": "Diplokokus gram-negatif intrasel (gonore); ≥2 leukosit/lapang pandang besar."}, {"l": "NAAT", "x": "Baku emas untuk Chlamydia dan Neisseria."}, {"l": "Skrining", "x": "Uji untuk IMS lain (sifilis, HIV, hepatitis B) dan terapi pasangan."}], "src": "(Workowski et al., 2021)"}, {"t": "Tatalaksana", "items": [{"l": "Gonore", "x": "Seftriakson 500 mg IM dosis tunggal (CDC 2021)."}, {"l": "Chlamydia", "x": "Doksisiklin 100 mg 2×/hari selama 7 hari."}, {"l": "Pasangan seksual", "x": "Diperiksa dan diterapi; hindari hubungan seksual sampai tuntas."}], "src": "(Workowski et al., 2021)"}, {"t": "Komplikasi", "items": [{"l": "Pria", "x": "Epididimitis, prostatitis, striktur uretra, infertilitas."}, {"l": "Wanita", "x": "Penyakit radang panggul, kehamilan ektopik, infertilitas."}, {"l": "Sistemik", "x": "Artritis reaktif (sindrom Reiter), infeksi gonokokal diseminata."}], "src": "(Workowski et al., 2021; Partin et al., 2020)"}]}, {"id": 23, "judul": "Inkontinensia Urin & Overactive Bladder (OAB)", "kat": "Urologi", "ciri": "Stres (batuk/bersin), urgensi (OAB), overflow (residu tinggi), campuran; mulai dengan terapi perilaku.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Inkontinensia urin", "x": "Keluarnya urin tak terkendali."}, {"l": "Stres", "x": "Bocor saat tekanan intraabdomen naik (batuk, bersin); kelemahan dasar panggul/sfingter."}, {"l": "Urgensi/OAB", "x": "Urgensi ± inkontinensia urgensi, frekuensi, nokturia tanpa ISK; overaktivitas detrusor."}, {"l": "Overflow dan fungsional", "x": "Overflow: obstruksi atau detrusor underactive; fungsional: gangguan mobilitas/kognitif."}], "src": "(EAU, 2025i; Partin et al., 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Stres", "x": "Hipermobilitas uretra atau defisiensi sfingter intrinsik."}, {"l": "OAB", "x": "Kontraksi detrusor involunter."}, {"l": "Overflow", "x": "Buli penuh melampaui kapasitas."}], "src": "(EAU, 2025i; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Stres", "x": "Bocor sedikit saat batuk, tertawa, olahraga."}, {"l": "Urgensi", "x": "Dorongan kuat mendadak berkemih, tidak sempat ke toilet."}, {"l": "Overflow", "x": "Menetes terus, pancar lemah, buli teraba."}], "src": "(EAU, 2025i)"}, {"t": "Diagnosis", "items": [{"l": "Anamnesis dan catatan berkemih", "x": "Bladder diary, kuesioner gejala."}, {"l": "Pemeriksaan", "x": "Tes batuk (stres), pemeriksaan panggul/prostat, status neurologis."}, {"l": "Penunjang", "x": "Urinalisis, residu urin; urodinamik bila akan dioperasi atau kasus kompleks."}], "src": "(EAU, 2025i)"}, {"t": "Tatalaksana", "items": [{"l": "Perilaku", "x": "Penurunan berat badan, bladder training, latihan otot dasar panggul (Kegel), atur asupan cairan/kafein."}, {"l": "OAB farmakologis", "x": "Antimuskarinik (solifenacin) atau β3-agonis (mirabegron, vibegron); hati-hati antikolinergik pada lansia."}, {"l": "Refrakter", "x": "Injeksi botulinum toksin intradetrusor, neuromodulasi sakral."}, {"l": "Stres", "x": "Sling midurethral atau bulking agent bila gagal terapi konservatif."}], "src": "(EAU, 2025i)"}, {"t": "Komplikasi", "items": [{"l": "Kulit dan ISK", "x": "Dermatitis, ISK berulang."}, {"l": "Jatuh dan fraktur", "x": "Terutama pada lansia dengan urgensi/nokturia."}, {"l": "Psikososial", "x": "Isolasi sosial, depresi."}], "src": "(EAU, 2025i; Partin et al., 2020)"}]}, {"id": 24, "judul": "Disfungsi Ereksi (DE)", "kat": "Urologi", "ciri": "Gagal mencapai/mempertahankan ereksi ≥3 bulan; vaskulogenik tersering; PDE5i kontraindikasi dengan nitrat.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Disfungsi ereksi", "x": "Ketidakmampuan menetap mencapai atau mempertahankan ereksi yang cukup untuk hubungan seksual (umumnya ≥3 bulan)."}, {"l": "Organik", "x": "Vaskulogenik (tersering), neurogenik, endokrin (hipogonadisme), struktural (penyakit Peyronie)."}, {"l": "Faktor risiko", "x": "DM, hipertensi, dislipidemia, merokok, obesitas, depresi."}, {"l": "Obat", "x": "β-blocker, tiazid, SSRI, antiandrogen."}], "src": "(EAU, 2025g; Partin et al., 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Relaksasi otot polos", "x": "Jalur NO–cGMP menyebabkan vasodilatasi arteri kavernosa dan ereksi."}, {"l": "Gangguan", "x": "Disfungsi endotel, kerusakan saraf, kebocoran venoocclusive, atau hormonal."}, {"l": "Penanda kardiovaskular", "x": "DE dapat mendahului penyakit jantung koroner."}], "src": "(EAU, 2025g; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Keluhan", "x": "Ereksi tidak cukup keras atau tidak bertahan."}, {"l": "Komorbid", "x": "Penurunan libido, gangguan ejakulasi, tekanan psikologis."}], "src": "(EAU, 2025g)"}, {"t": "Diagnosis", "items": [{"l": "Anamnesis seksual dan IIEF-5", "x": "22–25 normal; 17–21 ringan; 12–16 ringan-sedang; 8–11 sedang; 5–7 berat."}, {"l": "Pemeriksaan fisik", "x": "Genitalia, sensasi, status kardiovaskular."}, {"l": "Lab", "x": "Glukosa/HbA1c, lipid, testosteron; evaluasi risiko kardiovaskular."}], "src": "(EAU, 2025g)"}, {"t": "Tatalaksana", "items": [{"l": "Gaya hidup", "x": "Atasi faktor risiko, berhenti merokok, olahraga."}, {"l": "Lini pertama", "x": "Inhibitor PDE5 (sildenafil, tadalafil, vardenafil, avanafil); kontraindikasi dengan nitrat (hipotensi berat)."}, {"l": "Lini kedua/ketiga", "x": "Injeksi intrakavernosa alprostadil, alat vakum; prostesis penis."}, {"l": "Hipogonadisme", "x": "Terapi testosteron bila terbukti."}], "src": "(EAU, 2025g)"}, {"t": "Komplikasi", "items": [{"l": "Psikososial", "x": "Depresi, gangguan hubungan, penurunan kualitas hidup."}, {"l": "Penanda penyakit lain", "x": "Perlu evaluasi kardiovaskular dan metabolik."}], "src": "(EAU, 2025g)"}]}, {"id": 25, "judul": "Kelainan Urogenital Anak: Fimosis/Parafimosis, Kriptorkismus, Hipospadia", "kat": "Urologi", "ciri": "Parafimosis = emergensi; kriptorkismus: orkidopeksi 6–12 bulan (maks. 18 bulan); hipospadia: jangan sirkumsisi dahulu.", "bagian": [{"t": "Definisi & Etiologi", "items": [{"l": "Fimosis", "x": "Preputium tidak dapat ditarik; fisiologis pada anak kecil, patologis pada BXO atau ISK berulang."}, {"l": "Parafimosis", "x": "Preputium tertarik dan terjepit di belakang glans (emergensi)."}, {"l": "Kriptorkismus", "x": "Testis tidak berada di skrotum (turun tak sempurna)."}, {"l": "Hipospadia", "x": "Muara uretra di sisi ventral penis; sering disertai chordee."}], "src": "(EAU, 2025d; Partin et al., 2020)"}, {"t": "Patofisiologi", "items": [{"l": "Fimosis/parafimosis", "x": "Aderensi preputium dan inflamasi; parafimosis menyebabkan edema dan gangguan vaskular glans."}, {"l": "Kriptorkismus", "x": "Gangguan hormonal/anatomi pada penurunan testis; suhu tinggi mengganggu spermatogenesis."}, {"l": "Hipospadia", "x": "Gangguan perkembangan uretra dan preputium (hormonal/genetik)."}], "src": "(Partin et al., 2020; Kumar et al., 2023)"}, {"t": "Manifestasi Klinis", "items": [{"l": "Fimosis", "x": "Ballooning saat berkemih, ISK, balanopostitis."}, {"l": "Parafimosis", "x": "Nyeri, glans membengkak dan kebiruan."}, {"l": "Kriptorkismus", "x": "Skrotum kosong, testis teraba di inguinal atau tidak teraba."}, {"l": "Hipospadia", "x": "Pancar urin menyimpang, kulup berbentuk 'hooded'."}], "src": "(EAU, 2025d)"}, {"t": "Diagnosis", "items": [{"l": "Klinis", "x": "Diagnosis berdasarkan pemeriksaan fisik."}, {"l": "Kriptorkismus tidak teraba", "x": "Pencitraan atau laparoskopi untuk lokasi testis."}, {"l": "Hipospadia berat", "x": "Evaluasi kelainan seks/gangguan perkembangan seks."}], "src": "(EAU, 2025d)"}, {"t": "Tatalaksana", "items": [{"l": "Fimosis", "x": "Krim steroid topikal; sirkumsisi bila tidak berhasil atau BXO/ISK berulang."}, {"l": "Parafimosis", "x": "Reduksi manual segera; insisi dorsal bila gagal."}, {"l": "Kriptorkismus", "x": "Orkidopeksi sekitar usia 6–12 bulan (maksimal 18 bulan)."}, {"l": "Hipospadia", "x": "Koreksi bedah sekitar usia 6–18 bulan; hindari sirkumsisi sebelum operasi."}], "src": "(EAU, 2025d)"}, {"t": "Komplikasi", "items": [{"l": "Kriptorkismus", "x": "Infertilitas, risiko keganasan testis, torsio."}, {"l": "Parafimosis", "x": "Nekrosis glans."}, {"l": "Hipospadia", "x": "Fistula uretrokutan, striktur, pembengkokan penis."}], "src": "(EAU, 2025d; Partin et al., 2020)"}]}];
